import glob, sys
n = s = 0
for f in sorted(glob.glob("reports/*.txt")):
    for line in open(f):
        p = line.split()
        if len(p) < 4:
            continue
        st = p[1]
        is5xx = st == "5xx" or (len(st) == 3 and st.isdigit() and st[0] == "5")
        if is5xx and p[2] == "payments":
            n += 1
            s += int(p[3].rstrip("ms"))
try:
    got_n = int(open("count.txt").read().strip())
    got_s = int(open("sum.txt").read().strip())
except Exception as e:
    print(f"count.txt/sum.txt unreadable: {e}", file=sys.stderr)
    sys.exit(1)
if (got_n, got_s) != (n, s):
    print(f"expected count={n} sum={s}; got count={got_n} sum={got_s}", file=sys.stderr)
    sys.exit(1)
sys.exit(0)

